"""Report generator producing traceable Markdown and JSON reports."""
from __future__ import annotations
import json
from datetime import datetime, timezone
from pathlib import Path
from app.models.schemas import ResearchReport
from app.config import config

class ReportGenerator:
    def render_markdown(self, report: ResearchReport) -> str:
        timestamp=report.generated_at.strftime("%Y-%m-%d %H:%M:%S UTC")
        lines=[f"# Academic Research Report: {report.research_question}",f"\n*Generated by Lightweight Academic Research Agent on {timestamp}*\n","---","## 1. Research Question",f"> **{report.research_question}**\n","## 2. Executive Summary",f"{report.executive_summary}\n"]
        if report.comparative:
            lines += ["## Comparison", f"Compared entities: {', '.join(report.entities)}", ""]
            if report.comparison_table:
                headers=list(report.comparison_table[0].keys())
                lines += ["| " + " | ".join(headers) + " |", "| " + " | ".join([":---"]*len(headers)) + " |"]
                for row in report.comparison_table:
                    lines.append("| " + " | ".join(str(row.get(h,"insufficient evidence retrieved")).replace("|","\\|") for h in headers) + " |")
            else:
                lines.append("Insufficient evidence retrieved to construct a fully evidenced comparison table.")
            lines.append("")
        lines += ["## 3. Research Methodology", report.research_methodology+"", "## 4. Academic Sources Searched", "The following independent academic sources and registries were queried:"]
        lines += [f"- **{s.replace('_',' ').title()}**" for s in report.academic_sources_searched]
        lines += ["", "## 5. Search Strategy", report.search_strategy_summary+"", "## 6. Key Findings"]
        lines += [f"{i}. {x}" for i,x in enumerate(report.key_findings,1)] + ["", "## 7. Evidence Table", "| Evidence ID | Claim ID | Paper ID | Evidence Type | Strength | Extracted Excerpt |", "| :--- | :--- | :--- | :--- | :--- | :--- |"]
        if report.evidence_records:
            for ev in report.evidence_records:
                ex=ev.quote_or_excerpt.replace("|","\\|"); ex=ex[:87]+"..." if len(ex)>90 else ex
                lines.append(f"| {ev.evidence_id} | {ev.claim_id} | [{ev.paper_id}] | {ev.evidence_type.value} | `{ev.strength.value}` | {ex} |")
        else: lines.append("| — | — | — | — | — | No specific evidence records captured |")
        lines += ["", "## 8. Supporting Evidence"]
        supporting=[c for c in report.claims if c.evidence_type.value in ("empirical result","methodological claim","comparison")]
        lines += ([f"- **Claim ({c.evidence_type.value})**: {c.claim_text}\n  - **Supporting Sources**: {', '.join(f'[{s}]' for s in c.supporting_sources) if c.supporting_sources else f'[{c.paper_id}]'} | **Strength**: `{c.evidence_strength.value}` | **Confidence**: {c.confidence:.2f}" for c in supporting] or ["No independent empirical support records isolated."])
        lines += ["", "## 9. Contradictory Evidence & Scientific Disagreements", "| Technical Point / Claim | Supporting Papers | Contradicting / Caveat Papers | Overall Assessment |", "| :--- | :--- | :--- | :--- |"]
        if report.contradictions:
            for c in report.contradictions: lines.append(f"| {c.claim.replace('|','\\|')} | {', '.join(f'[{p}]' for p in c.supporting_papers) or 'None'} | {', '.join(f'[{p}]' for p in c.contradicting_papers) or 'None'} | {c.overall_assessment.replace('|','\\|')} |")
        else: lines.append("| No substantial empirical contradictions detected | — | — | No contradiction found in retrieved sample |")
        lines += ["", "## 10. Method / Approach Comparison", "| Paper ID | Title | Year | Venue | Classification / Tier | Citations |", "| :--- | :--- | :--- | :--- | :--- | :--- |"]
        for c in report.method_comparisons: lines.append(f"| [{c['paper_id']}] | {str(c['title']).replace('|','\\|')[:60]} | {c['year']} | {c.get('venue') or 'Preprint'} | `{c.get('tier')}` | {c.get('citations',0)} |")
        lines += ["", "## 11. Limitations in Existing Research"] + [f"- {x}" for x in report.limitations_in_existing_research]
        lines += ["", "## 12. Classified Research Gaps"]
        for g in report.research_gaps:
            lines += [f"### {g.gap_id}: {g.category.value.title()}",f"- **Description**: {g.description}",f"- **Evidenced by**: {', '.join(f'[{e}]' for e in g.supporting_evidence) or 'N/A'}","- **Proposed Future Directions:**"]+[f"  - {d}" for d in g.proposed_directions]+[""]
        lines += ["## 13. Open Research Questions"]+[f"{i}. {q}" for i,q in enumerate(report.open_research_questions,1)]+["", "## 14. Evidence Strength & Uncertainty Evaluation", report.evidence_strength_summary+"", "> Evidence strength is an internal epistemic heuristic, not a statistical probability.", "", "## 15. Conclusion", report.conclusion+"", "## 16. References", "All citations used map deterministically to retrieved records below:"]
        for p in report.papers:
            authors=", ".join(p.authors[:4])+(" et al." if len(p.authors)>4 else "") if p.authors else "Unknown Authors"
            doi=f" DOI: [{p.doi}](https://doi.org/{p.doi})" if p.doi else ""; url=f" [Source URL]({p.url})" if p.url and not p.doi else ""
            lines.append(f"- **[{p.internal_id}]** {authors} ({p.year or 'N/A'}). **{p.title}**.{(' *'+p.venue+'*') if p.venue else ''}.{doi}{url} `[{', '.join(p.sources)}]`")
        return "\n".join(lines)

    def save_report(self, report: ResearchReport, output_dir: Path | None = None) -> tuple[Path, Path]:
        target=output_dir or config.REPORTS_DIR; target.mkdir(parents=True,exist_ok=True); slug=datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
        md=target/f"research_{slug}.md"; js=target/f"research_{slug}.json"
        md.write_text(self.render_markdown(report),encoding="utf-8"); js.write_text(json.dumps(report.model_dump(mode="json"),indent=2,ensure_ascii=False),encoding="utf-8")
        return md,js
